            C#

    using System;
using System.Collections.Generic;

// Code Addition(C#)
// C# contribution to existing topic 
// "Graph implementation using STL for 
// competitive programming | Set 2 (Weighted graph)"
class WeightedGraph
   {
       private int V;

       private LinkedList<Tuple<int, int>>[] adj;

       public WeightedGraph(int v)
       {
           this.V = v;

           adj = new LinkedList<Tuple<int, int>>[v];

           for (int i=0;i < v; i++)
           {
               adj[i] = new LinkedList<Tuple<int, int>>();
           }
       }


       public void addEdge(int u, int v, int wt)
       {
           adj[u].AddLast(Tuple.Create(v, wt));
           adj[v].AddLast(Tuple.Create(u, wt));

       }

       public void printGraph()
       {
           for (int i=0; i< this.V;i++)
           {
               Console.WriteLine("\nNode " + i + " makes an edge with ");
               foreach (var j in adj[i])
               {
                   Console.WriteLine("\tNode " + j.Item1 + " with edge weight " + j.Item2 + " ");
               }

           }
       }

       static void Main(string[] args)
       {

           int V = 5;
           WeightedGraph stl = new WeightedGraph(V);


           stl.addEdge(0, 1, 10);
           stl.addEdge(0, 4, 20);
           stl.addEdge(1, 2, 30);
           stl.addEdge(1, 3, 40);
           stl.addEdge(1, 4, 50);
           stl.addEdge(2, 3, 60);
           stl.addEdge(3, 4, 70);
           stl.printGraph();

           Console.ReadKey();

       }
   }

